<template><view class="page"><view class="nav" @tap="back">‹</view><scroll-view scroll-y class="scroll"><view class="hero"><text>六爻算卦</text><small>心诚则灵 · 仅作自省与决策参考</small></view><view class="panel"><text class="label">所问何事</text><textarea v-model="question" placeholder="例如：这次工作变动应当如何准备？" auto-height maxlength="100"/><text class="label">起卦方式</text><view class="methods"><view v-for="m in methods" :key="m.key" :class="['method',method===m.key&&'active']" @tap="method=m.key">{{m.name}}</view></view><view v-if="method==='numbers'" class="nums"><input v-model.number="numbers[0]" type="number" placeholder="第一个数字"/><input v-model.number="numbers[1]" type="number" placeholder="第二个数字"/></view><button class="cast" :loading="loading" @tap="doCast">{{method==='coins'?'摇动三枚铜钱':'开始起卦'}}</button></view><view v-if="result" class="panel result"><view class="hexagram-display"><view class="hexagram-col"><view class="hexagram-title"><small>本卦</small><text>{{result.original.name}}</text><text class="sub-info">{{result.original.upper.symbol}} {{result.original.upper.name}}上 · {{result.original.lower.symbol}} {{result.original.lower.name}}下</text></view><view class="yao-stack"><view v-for="line in [...result.lines].reverse()" :key="'orig-'+line.index" :class="['yao-item',line.moving&&'moving']"><view class="yao-line" :class="{yang:line.yang}"></view><text class="yao-label">第{{line.index}}爻</text><text v-if="line.moving" class="moving-tag">动</text></view></view></view><view v-if="result.changed" class="hexagram-col"><view class="hexagram-title"><small>变卦</small><text>{{result.changed.name}}</text><text class="sub-info">{{result.changed.upper.symbol}} {{result.changed.upper.name}}上 · {{result.changed.lower.symbol}} {{result.changed.lower.name}}下</text></view><view class="yao-stack"><view v-for="line in getChangedLines()" :key="'changed-'+line.index" class="yao-item"><view class="yao-line" :class="{yang:line.yang}"></view><text class="yao-label">第{{line.index}}爻</text></view></view></view></view><text class="summary">{{result.summary}}</text><button class="interpret" :loading="interpreting" @tap="doInterpret">{{interpretation?'重新 AI 解读':'AI 解读此卦'}}</button><view v-if="interpretation" class="answer"><text>卦象解读</text><text>{{interpretation}}</text></view></view></scroll-view></view></template>
<script setup lang="ts">import {ref} from 'vue';import {castLiuYao,interpretLiuYao,type LiuYaoResult} from '@/api';const methods=[{key:'coins',name:'铜钱起卦'},{key:'numbers',name:'数字起卦'},{key:'time',name:'时间起卦'}] as const;const method=ref<typeof methods[number]['key']>('coins'),question=ref(''),numbers=ref<number[]>([]),loading=ref(false),interpreting=ref(false),result=ref<LiuYaoResult|null>(null),interpretation=ref('');function back(){uni.navigateBack()}async function doCast(){if(method.value==='numbers'&&(!Number.isInteger(numbers.value[0])||!Number.isInteger(numbers.value[1]))){uni.showToast({title:'请输入两个整数',icon:'none'});return}loading.value=true;try{result.value=await castLiuYao(method.value,numbers.value);interpretation.value=''}catch(e:any){uni.showToast({title:e.message||'起卦失败',icon:'none'})}finally{loading.value=false}}async function doInterpret(){if(!result.value||!question.value.trim()){uni.showToast({title:'请先填写问题并起卦',icon:'none'});return}interpreting.value=true;try{interpretation.value=(await interpretLiuYao(question.value,result.value)).interpretation}catch(e:any){uni.showToast({title:e.message||'解读失败',icon:'none'})}finally{interpreting.value=false}}
function getChangedLines(){if(!result.value?.changed)return[];return[...result.value.lines].map(line=>({...line,yang:line.moving?!line.yang:line.yang})).reverse()}</script>
<style lang="scss">.page{min-height:100vh;background:linear-gradient(#14100b,#302313);color:#f0e4c7}.scroll{height:100vh}.nav{position:fixed;z-index:2;top:50rpx;left:28rpx;font-size:60rpx}.hero{text-align:center;padding:140rpx 0 64rpx}.hero text,.hero small{display:block}.hero text{font-size:64rpx;letter-spacing:14rpx;color:#f0cf7b}.hero small{margin-top:24rpx;color:#c7af79;font-size:28rpx}.panel{margin:32rpx 36rpx;padding:40rpx 36rpx;border:1rpx solid rgba(235,194,104,.28);border-radius:24rpx;background:rgba(255,255,255,.04)}.label{display:block;color:#e8c777;margin:20rpx 0 16rpx;font-size:30rpx;font-weight:600;letter-spacing:2rpx}.panel textarea{width:100%;box-sizing:border-box;padding:24rpx;background:#21180d;color:#fff;border-radius:14rpx;font-size:29rpx;line-height:1.7;min-height:120rpx}.methods{display:flex;gap:18rpx;margin-top:8rpx}.method{flex:1;text-align:center;padding:24rpx 12rpx;border:1rpx solid #745c32;border-radius:14rpx;color:#cbb887;font-size:29rpx;transition:all .25s}.method.active{background:#80632a;color:#fff;border-color:#b58b35}.nums{display:flex;gap:28rpx;margin-top:32rpx}.nums input{flex:1;min-width:0;box-sizing:border-box;padding:32rpx 28rpx;height:120rpx;background:#21180d;color:#fff;border-radius:18rpx;font-size:34rpx;line-height:1.6}.cast,.interpret{margin-top:40rpx;padding:28rpx;background:linear-gradient(135deg,#b58b35,#e7bd67);color:#271b08;font-size:32rpx;font-weight:600;border-radius:16rpx;letter-spacing:4rpx}.result{margin-bottom:100rpx}.hexagram-display{display:flex;justify-content:center;gap:48rpx;margin:40rpx 0;padding:28rpx;background:rgba(255,255,255,.02);border-radius:20rpx;border:1rpx solid rgba(235,194,104,.15)}.hexagram-col{flex:1;max-width:320rpx;text-align:center}.hexagram-title small,.hexagram-title text{display:block}.hexagram-title small{font-size:22rpx;color:#c7af79;margin-bottom:10rpx;letter-spacing:2rpx}.hexagram-title text:first-of-type{font-size:38rpx;color:#efd089;margin:8rpx 0;font-weight:700;letter-spacing:4rpx}.sub-info{font-size:23rpx;color:#bca57a;margin-top:6rpx;line-height:1.5}.yao-stack{margin-top:24rpx;display:flex;flex-direction:column-reverse;gap:14rpx}.yao-item{display:flex;align-items:center;gap:16rpx;height:52rpx;position:relative}.yao-line{width:100%;height:12rpx;border-radius:6rpx;background:linear-gradient(90deg,#dcc077 0 42%,transparent 42% 58%,#dcc077 58%);transition:all .3s}.yao-line.yang{background:linear-gradient(90deg,#f0cf7b,#e7bd67);box-shadow:0 2rpx 12rpx rgba(240,207,123,.4)}.yao-item.moving .yao-line{animation:yaoGlow 2s ease-in-out infinite}@keyframes yaoGlow{0%,100%{box-shadow:0 0 8rpx #f3d075}50%{box-shadow:0 0 24rpx #f3d075,0 0 40rpx rgba(243,208,117,.4)}}.yao-label{width:80rpx;color:#bca57a;font-size:24rpx;flex-shrink:0}.moving-tag{position:absolute;right:-60rpx;color:#f0ce75;font-size:24rpx;font-weight:700;background:rgba(240,206,117,.15);padding:4rpx 14rpx;border-radius:8rpx;border:1rpx solid rgba(240,206,117,.3)}.summary{display:block;text-align:center;line-height:1.9;color:#d8c7a3;margin:36rpx 0;font-size:29rpx;padding:0 8rpx}.answer{margin-top:32rpx;padding:32rpx;background:rgba(255,255,255,.06);border-radius:16rpx}.answer text{display:block;line-height:2;font-size:29rpx}.answer text:first-child{color:#efcf83;margin-bottom:16rpx;font-size:32rpx;font-weight:600;letter-spacing:2rpx}</style>